const now = new Date();
const arabicMonths = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
const arabicDays = ['الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
function toArabicNumerals(num) {
  const arabicNumerals = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
  return num.toString().split('').map(d => arabicNumerals[parseInt(d)] || d).join('');
}
const dateArabic = `${arabicDays[now.getDay()]}، ${toArabicNumerals(now.getDate())} ${arabicMonths[now.getMonth()]} ${toArabicNumerals(now.getFullYear())}`;
return { json: { date_arabic: dateArabic, date_english: now.toISOString().split('T')[0] } };

// Get all items from merged SERP results
const allItems = $input.all();

let uaeNews = [];
let gccNews = [];
let intlNews = [];
let orgNews = [];

// Process each SERP result
for (const item of allItems) {
  const data = item.json;
  const query = data.search_parameters?.q || '';

  // Extract news results
  const newsResults = data.news_results || [];
  const news = newsResults.slice(0, 10).map(n => ({
    title: n.title,
    source: n.source?.name || n.source || 'Unknown',
    snippet: n.snippet || '',
    link: n.link
  }));

  // Categorize based on search query
  if (query.includes('UAE') || query.includes('Dubai')) {
    uaeNews = news;
  } else if (query.includes('Saudi') || query.includes('Kuwait')) {
    gccNews = news;
  } else if (query.includes('international') || query.includes('Europe')) {
    intlNews = news;
  } else if (query.includes('INTERPOL') || query.includes('FBI')) {
    // Organizations search uses organic_results
    const orgResults = data.organic_results || [];
    orgNews = orgResults.slice(0, 10).map(n => ({
      title: n.title,
      source: 'Organization',
      snippet: n.snippet || '',
      link: n.link
    }));
  }
}

return {
  json: {
    uae_news: uaeNews,
    gcc_news: gccNews,
    international_news: intlNews,
    org_news: orgNews,
    total: uaeNews.length + gccNews.length + intlNews.length + orgNews.length
  }
};

const analysis = $json.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const citations = $json.citations || [];
const now = new Date();
const dateArabic = now.toLocaleDateString('ar-AE', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const dateEnglish = now.toISOString().split('T')[0];
const reportTitle = `التقرير اليومي للرصد الجنائي - ${dateArabic}`;

// Format content with proper HTML structure
let formattedContent = analysis
  .replace(/---/g, '')
  .replace(/## (.*)/g, '</div></div><div class="section"><h2>$1</h2><div class="section-content">')
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
  .replace(/\*(.*?)\*/g, '<em>$1</em>')
  .replace(/- \*([^:]+):\*/\s*/g, '<div class="field"><span class="field-label">$1:</span> ')
  .replace(/^- /gm, '<li>')
  .replace(/\n\n/g, '</p><p>')
  .replace(/\n/g, '<br>');

// Add Perplexity citations if available
let citationsHtml = '';
if (citations.length > 0) {
  citationsHtml = `<div class="section references"><h2>مراجع إضافية من Perplexity</h2><ul>${citations.map(c => `<li><a href="${c}" target="_blank">${c}</a></li>`).join('')}</ul></div>`;
}

const htmlReport = `<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head>
  <meta charset="UTF-8">
  <title>${reportTitle}</title>
  <style>
    body { font-family: 'Segoe UI', Tahoma, Arial, sans-serif; direction: rtl; text-align: right; line-height: 1.9; padding: 20px; max-width: 950px; margin: 0 auto; background: #f0f4f8; }
    .container { background: white; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.1); }
    .header { background: linear-gradient(135deg, #1a365d, #2c5282); color: white; padding: 30px; text-align: center; border-radius: 12px 12px 0 0; margin: -40px -40px 30px; }
    .header h1 { margin: 0 0 10px; font-size: 26px; font-weight: 600; }
    .header .subtitle { font-size: 14px; opacity: 0.9; }
    .section { margin-bottom: 30px; padding: 25px; background: #f8fafc; border-radius: 10px; border-right: 5px solid #2c5282; }
    .section h2 { color: #1a365d; margin: 0 0 20px; font-size: 20px; border-bottom: 2px solid #e2e8f0; padding-bottom: 12px; }
    .section-content { color: #2d3748; font-size: 15px; }
    .section-content p { margin: 0 0 15px; }
    .field { margin: 8px 0; padding: 8px 12px; background: white; border-radius: 6px; border-right: 3px solid #4299e1; }
    .field-label { font-weight: 600; color: #2b6cb0; }
    .section-content li { margin-bottom: 10px; padding-right: 10px; }
    .section-content ul { margin: 15px 0; padding-right: 25px; }
    .executive { background: linear-gradient(135deg, #ebf8ff, #f0fff4); border-right-color: #38a169; }
    .recommendations { background: #fffaf0; border-right-color: #dd6b20; }
    .recommendations h2 { color: #c05621; }
    .references { background: #f0fff4; border-right-color: #38a169; }
    .references h2 { color: #276749; }
    .references ul { margin: 0; padding: 0 20px; }
    .references li { margin-bottom: 8px; word-break: break-all; }
    .references a { color: #2b6cb0; text-decoration: none; }
    .references a:hover { text-decoration: underline; }
    .risk-high { color: #c53030; font-weight: bold; }
    .risk-medium { color: #dd6b20; font-weight: bold; }
    .risk-low { color: #38a169; font-weight: bold; }
    .footer { text-align: center; padding: 25px; color: #718096; font-size: 13px; border-top: 2px solid #e2e8f0; margin-top: 30px; }
    .footer .disclaimer { font-size: 11px; margin-top: 10px; color: #a0aec0; }
    @media print { body { background: white; } .container { box-shadow: none; } }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>التقرير اليومي للرصد الجنائي والأمني</h1>
      <div class="subtitle">حكومة الإمارات العربية المتحدة</div>
      <div>${dateArabic}</div>
    </div>
    <div class="section executive">
      <div class="section-content">
        ${formattedContent}
      </div>
    </div>
    ${citationsHtml}
    <div class="footer">
      <div>تم إعداد هذا التقرير آلياً بواسطة نظام الرصد الجنائي الذكي</div>
      <div class="disclaimer">هذا التقرير سري ومخصص للاستخدام الرسمي فقط</div>
    </div>
  </div>
</body>
</html>`;

return {
  json: {
    report_html: htmlReport,
    report_title: reportTitle,
    file_name: `criminal_intelligence_report_${dateEnglish}.html`,
    date: dateEnglish
  },
  binary: {
    report_file: {
      data: Buffer.from(htmlReport).toString('base64'),
      mimeType: 'text/html',
      fileName: `criminal_intelligence_report_${dateEnglish}.html`
    }
  }
};
